import React from 'react';
import { formatDistanceToNow } from 'date-fns';

const NewsCard = ({ article }) => {
  const {
    title,
    description,
    summary,
    image_url,
    source,
    category,
    published_at,
    related_topics = [],
    trending_score
  } = article;

  const publishedDate = published_at ? new Date(published_at) : new Date();
  const timeAgo = formatDistanceToNow(publishedDate, { addSuffix: true });

  return (
    <div className="news-card">
      {image_url && (
        <img 
          src={image_url} 
          alt={title} 
          className="news-image"
          onError={(e) => {
            e.target.src = 'https://via.placeholder.com/300x200?text=News';
          }}
        />
      )}
      <div className="news-content">
        <div className="news-meta">
          <span className="news-source">{source}</span>
          <span className="news-category">{category}</span>
        </div>
        
        <h3 className="news-title">{title}</h3>
        <p className="news-description">{description}</p>
        
        {summary && (
          <div className="news-summary">
            <strong>🤖 AI Summary:</strong> {summary}
          </div>
        )}
        
        <div className="news-meta">
          <span className="news-time">{timeAgo}</span>
          {trending_score > 0.7 && (
            <span className="trending-badge">🔥 Trending</span>
          )}
        </div>
        
        {related_topics.length > 0 && (
          <div className="news-related">
            {related_topics.map((topic, index) => (
              <span key={index} className="related-topic">
                #{topic}
              </span>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default NewsCard;
